export const modules = [
  {id:0,title:'Знакомство с Python',subtitle:'Сначала — просто попробуем',icon:'terminal',color:'green',tags:['print()','переменные','input()'],description:'Выводи текст, сохраняй значения и знакомь программу с пользователем.',theory:`<h3>Привет, Python!</h3><p>Программа — это последовательность инструкций. Python выполняет их сверху вниз. Строки записывают в кавычках, а <code>print()</code> выводит результат.</p><pre>print("Привет!")\nname = "Саша"\nprint("Привет, " + name + "!")</pre><p>Переменная хранит значение. Оператор <code>=</code> присваивает его имени слева. Функция <code>input()</code> читает одну строку ввода. Параметр <code>sep</code> меняет разделитель при выводе.</p><pre>name = input()\nprint("Привет, " + name + "!")\nprint("раз", "два", sep=" — ")</pre><p>В задачах используй <code>input()</code> без текста приглашения: проверка сравнивает весь вывод программы.</p>`},
  {id:1,title:'Числа и вычисления',subtitle:'Дадим коду немного математики',icon:'calculator',color:'blue',tags:['int()','арифметика','типы'],description:'Превращай строки в числа, считай и используй остаток от деления.',theory:`<h3>Python умеет считать</h3><p><code>input()</code> возвращает строку. Для целого числа используй <code>int()</code>, для дробного — <code>float()</code>.</p><pre>a = int(input())\nb = int(input())\nprint(a + b)</pre><p>Операции: <code>+</code> сложение, <code>-</code> вычитание, <code>*</code> умножение, <code>/</code> деление, <code>**</code> степень. <code>//</code> даёт целую часть частного, <code>%</code> — остаток.</p><pre>minutes = 135\nprint(minutes // 60)  # 2\nprint(minutes % 60)   # 15\nprint(round(3.14159, 2))  # 3.14</pre>`},
  {id:2,title:'Условия и решения',subtitle:'Научим программу выбирать',icon:'branch',color:'purple',tags:['if / else','сравнения','логика'],description:'Добавляй развилки и принимай решения в зависимости от входных данных.',theory:`<h3>Если… то… иначе</h3><p>Блок <code>if</code> выполняется, когда условие истинно. <code>elif</code> проверяет другое условие, <code>else</code> обрабатывает остальные случаи. После условия ставят двоеточие, внутри блока — отступ в 4 пробела.</p><pre>age = int(input())\nif age >= 18:\n    print("Можно")\nelse:\n    print("Пока рано")</pre><p>Сравнения: <code>==</code>, <code>!=</code>, <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>. Условия объединяют с помощью <code>and</code>, <code>or</code>, <code>not</code>.</p><pre>if n > 0:\n    print("плюс")\nelif n < 0:\n    print("минус")\nelse:\n    print("ноль")</pre>`},
  {id:3,title:'Циклы и повторения',subtitle:'Меньше рутины, больше кода',icon:'repeat',color:'peach',tags:['for','while','range()'],description:'Повторяй действия, накапливай результат и находи закономерности.',theory:`<h3>Один раз напиши, много раз повтори</h3><p><code>for</code> перебирает элементы. <code>range(start, stop)</code> создаёт числа от start до stop, не включая stop. Третий аргумент задаёт шаг.</p><pre>for i in range(1, 6):\n    print(i)\n\ntotal = 0\nfor i in range(1, 4):\n    total += i\nprint(total)  # 6</pre><p><code>while</code> повторяет блок, пока условие истинно. Не забудь менять переменную, чтобы цикл завершился.</p><pre>n = 3\nwhile n > 0:\n    print(n)\n    n -= 1</pre><p>Строку тоже можно перебрать: <code>for letter in text:</code>. Оператор <code>in</code> проверяет, содержится ли элемент в последовательности.</p>`},
  {id:4,title:'Строки и коллекции',subtitle:'Разложим всё по местам',icon:'layers',color:'pink',tags:['str','list','dict'],description:'Работай с текстом, списками и наборами данных.',theory:`<h3>Много значений в одной переменной</h3><p><code>len()</code> возвращает длину. Индексы начинаются с нуля, срез <code>[::-1]</code> переворачивает последовательность.</p><pre>text = "python"\nprint(len(text))    # 6\nprint(text[0])      # p\nprint(text[::-1])   # nohtyp</pre><p><code>split()</code> разбивает строку на слова. <code>map(int, ...)</code> превращает их в числа, <code>list()</code> собирает список. <code>set()</code> оставляет уникальные значения.</p><pre>nums = list(map(int, input().split()))\nprint(sum(nums))\nprint(len(set(nums)))</pre><p>Словарь связывает ключи со значениями. <code>get(key, 0)</code> возвращает 0, если ключ ещё не добавлен.</p><pre>counts = {}\nfor word in input().split():\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)</pre>`},
  {id:5,title:'Функции и свой проект',subtitle:'Соберём навыки воедино',icon:'code',color:'yellow',tags:['def','return','мини-проект'],description:'Пиши переиспользуемый код и собери свой первый небольшой проект.',theory:`<h3>Дай своему коду имя</h3><p>Функция — именованный блок кода. <code>def</code> объявляет её, параметры получают данные, а <code>return</code> возвращает результат.</p><pre>def square(number):\n    return number ** 2\n\nprint(square(5))  # 25</pre><p><code>print()</code> показывает значение, но не возвращает его. В задачах на функции нужен именно <code>return</code>. Наши тесты сами вызовут функцию с разными аргументами.</p><pre>def is_even(n):\n    return n % 2 == 0</pre><p>Документация, понятные имена и небольшие функции делают код удобным для чтения. В финальном проекте объедини функции, условия, списки и словари.</p>`}
];

const io = (input, expected) => ({input,expected});
const fn = (expr,expected,label) => ({expr,expected,label});
export const tasks = [
  {title:'Привет, мир!',brief:'Первая строка твоего Python-пути.',minutes:3,body:'Пусть программа поздоровается с миром. Выведи строку <code>Привет, мир!</code> — с запятой, пробелом и восклицательным знаком.',starter:'# Твоя первая программа\n',hint:'Передай текст в кавычках внутрь print(). Например: print("Твой текст").',solution:'print("Привет, мир!")',tests:[io('','Привет, мир!')]},
  {title:'Знакомься: переменная',brief:'Сохрани имя и выведи его.',minutes:4,body:'Создай переменную <code>name</code> со значением <code>Аня</code> и выведи её значение с помощью <code>print()</code>.',starter:'# Сохрани имя в переменную name\n',hint:'Имя переменной пишут слева от =, значение — справа. При выводе name не нужны кавычки.',solution:'name = "Аня"\nprint(name)',tests:[io('','Аня')],required:'"name" in ns and ns["name"] == "Аня"'},
  {title:'Две строки о себе',brief:'Порядок инструкций имеет значение.',minutes:4,body:'Выведи две строки: сначала <code>Я учу Python</code>, затем <code>И у меня получается!</code>. Каждый текст должен быть на отдельной строке.',starter:'# Выведи две строки по порядку\n',hint:'Каждый вызов print() по умолчанию заканчивается переходом на новую строку.',solution:'print("Я учу Python")\nprint("И у меня получается!")',tests:[io('','Я учу Python\nИ у меня получается!')]},
  {title:'Собери сообщение',brief:'Соедини несколько частей в одну строку.',minutes:5,body:'Дана переменная <code>language = "Python"</code>. Используй её, чтобы вывести <code>Я выбираю Python!</code>. Значение переменной language должно остаться прежним.',starter:'language = "Python"\n# Составь и выведи сообщение\n',hint:'Строки можно соединить знаком +: "Привет, " + name + "!".',solution:'language = "Python"\nprint("Я выбираю " + language + "!")',tests:[io('','Я выбираю Python!')],required:'ns.get("language") == "Python"'},
  {title:'Личное приветствие',brief:'Познакомь программу с пользователем.',minutes:6,body:'Прочитай имя из одной строки ввода. Выведи приветствие в формате <code>Привет, ИМЯ!</code>. Программа должна работать с любым именем.',starter:'name = input()\n# Поздоровайся по имени\n',hint:'input() читает строку. Добавь имя между "Привет, " и "!". Не добавляй приглашение к input().',solution:'name = input()\nprint("Привет, " + name + "!")',tests:[io('Аня','Привет, Аня!'),io('Марк','Привет, Марк!'),io('Лена','Привет, Лена!')]},
  {title:'Сумма двух чисел',brief:'Первое вычисление с вводом данных.',minutes:5,body:'На вход подаются два целых числа, каждое на отдельной строке. Выведи их сумму.',starter:'a = int(input())\nb = int(input())\n# Выведи сумму\n',hint:'int() превращает строку в целое число. Сложи a и b внутри print().',solution:'a = int(input())\nb = int(input())\nprint(a + b)',tests:[io('3\n7','10'),io('-5\n2','-3'),io('0\n0','0')]},
  {title:'Через год',brief:'Посчитай будущий возраст.',minutes:4,body:'Прочитай целое число — текущий возраст. Выведи, сколько лет будет человеку через год.',starter:'# Прочитай возраст и прибавь один\n',hint:'Сначала age = int(input()), затем выведи age + 1.',solution:'age = int(input())\nprint(age + 1)',tests:[io('19','20'),io('0','1'),io('99','100')]},
  {title:'Часы и минуты',brief:'Разберись с целочисленным делением.',minutes:6,body:'На вход подаётся неотрицательное количество минут. Выведи количество полных часов и оставшиеся минуты через пробел. Например, 135 минут — это <code>2 15</code>.',starter:'minutes = int(input())\n# Часы и оставшиеся минуты\n',hint:'minutes // 60 — полные часы, minutes % 60 — остаток. print(a, b) разделяет значения пробелом.',solution:'minutes = int(input())\nprint(minutes // 60, minutes % 60)',tests:[io('135','2 15'),io('59','0 59'),io('120','2 0'),io('0','0 0')]},
  {title:'Площадь и периметр',brief:'Два результата одной программы.',minutes:6,body:'Прочитай длину и ширину прямоугольника — два положительных целых числа на отдельных строках. Выведи площадь на первой строке, периметр — на второй.',starter:'a = int(input())\nb = int(input())\n',hint:'Площадь = a * b, периметр = 2 * (a + b). Выведи их двумя вызовами print().',solution:'a = int(input())\nb = int(input())\nprint(a * b)\nprint(2 * (a + b))',tests:[io('3\n4','12\n14'),io('1\n1','1\n4'),io('5\n10','50\n30')]},
  {title:'Цена со скидкой',brief:'Добавь дробные числа в расчёты.',minutes:6,body:'Прочитай цену с помощью <code>float(input())</code>. Применяй скидку 10% и выведи результат, округлив его до двух знаков с помощью <code>round(..., 2)</code>. Нули в конце добавлять не нужно: для 100 результат <code>90.0</code>.',starter:'price = float(input())\n',hint:'Цена со скидкой = price * 0.9. Выведи round(price * 0.9, 2).',solution:'price = float(input())\nprint(round(price * 0.9, 2))',tests:[io('100','90.0'),io('99.99','89.99'),io('0','0.0')]},
  {title:'Какой знак?',brief:'Три варианта вместо одного.',minutes:6,body:'Прочитай целое число. Если оно больше нуля, выведи <code>плюс</code>, меньше нуля — <code>минус</code>, равно нулю — <code>ноль</code>.',starter:'n = int(input())\n# Используй if, elif и else\n',hint:'Проверь n > 0, затем n < 0, а случай нуля оставь в else. Не забудь двоеточия и отступы.',solution:'n = int(input())\nif n > 0:\n    print("плюс")\nelif n < 0:\n    print("минус")\nelse:\n    print("ноль")',tests:[io('7','плюс'),io('-3','минус'),io('0','ноль')]},
  {title:'Чёт или нечёт',brief:'Остаток помогает принимать решения.',minutes:5,body:'Прочитай целое число. Выведи <code>чётное</code>, если оно делится на 2 без остатка, иначе — <code>нечётное</code>.',starter:'n = int(input())\n',hint:'У чётного числа n % 2 == 0. Ноль тоже чётный.',solution:'n = int(input())\nif n % 2 == 0:\n    print("чётное")\nelse:\n    print("нечётное")',tests:[io('8','чётное'),io('3','нечётное'),io('0','чётное'),io('-4','чётное')]},
  {title:'Можно войти?',brief:'Проверь граничное значение.',minutes:5,body:'Прочитай целый возраст. С 18 лет включительно выведи <code>Доступ открыт</code>, иначе — <code>Пока рано</code>.',starter:'age = int(input())\n',hint:'Проверь age >= 18, чтобы не забыть самого восемнадцатилетнего пользователя.',solution:'age = int(input())\nif age >= 18:\n    print("Доступ открыт")\nelse:\n    print("Пока рано")',tests:[io('18','Доступ открыт'),io('17','Пока рано'),io('30','Доступ открыт')]},
  {title:'Большее из трёх',brief:'Сравни несколько значений.',minutes:7,body:'Прочитай три целых числа с отдельных строк. Выведи наибольшее из них. Можно использовать условия или встроенную функцию <code>max()</code>.',starter:'a = int(input())\nb = int(input())\nc = int(input())\n',hint:'Сохрани a как текущий максимум. Сравни с b и c. Или используй max(a, b, c).',solution:'a = int(input())\nb = int(input())\nc = int(input())\nprint(max(a, b, c))',tests:[io('3\n9\n5','9'),io('-3\n-7\n-1','-1'),io('4\n4\n4','4')]},
  {title:'Оценка за тест',brief:'Собери цепочку условий.',minutes:7,body:'Прочитай целое количество баллов от 0 до 100. Выведи оценку: 90–100 — <code>5</code>, 70–89 — <code>4</code>, 50–69 — <code>3</code>, меньше 50 — <code>2</code>.',starter:'score = int(input())\n',hint:'Проверяй пороги сверху вниз: >= 90, >= 70, >= 50. Тогда диапазоны не пересекутся.',solution:'score = int(input())\nif score >= 90:\n    print(5)\nelif score >= 70:\n    print(4)\nelif score >= 50:\n    print(3)\nelse:\n    print(2)',tests:[io('90','5'),io('89','4'),io('70','4'),io('50','3'),io('49','2'),io('100','5')]},
  {title:'Раз, два, три…',brief:'Твоя первая автоматизация.',minutes:5,body:'С помощью цикла выведи числа от 1 до 5 включительно, каждое на отдельной строке.',starter:'# Используй for и range()\n',hint:'Верхняя граница range() не включается: нужен range(1, 6).',solution:'for i in range(1, 6):\n    print(i)',tests:[io('','1\n2\n3\n4\n5')],syntax:'loop'},
  {title:'Сумма до n',brief:'Накапливай результат по шагам.',minutes:7,body:'Прочитай положительное целое число n. Выведи сумму всех чисел от 1 до n включительно.',starter:'n = int(input())\ntotal = 0\n',hint:'Перебери range(1, n + 1) и прибавляй каждое число к total. Выведи total после цикла.',solution:'n = int(input())\ntotal = 0\nfor i in range(1, n + 1):\n    total += i\nprint(total)',tests:[io('5','15'),io('1','1'),io('10','55')]},
  {title:'Только чётные',brief:'Соедини цикл с условием.',minutes:7,body:'Прочитай целое n ≥ 2. Выведи все положительные чётные числа от 2 до n включительно, каждое на отдельной строке.',starter:'n = int(input())\n',hint:'Используй range(2, n + 1, 2) или проверяй i % 2 == 0 внутри обычного цикла.',solution:'n = int(input())\nfor i in range(2, n + 1, 2):\n    print(i)',tests:[io('8','2\n4\n6\n8'),io('3','2'),io('2','2')]},
  {title:'Факториал',brief:'Теперь не складываем, а умножаем.',minutes:8,body:'Прочитай целое число n от 0 до 12. Выведи n! — произведение целых чисел от 1 до n. Для нуля результат равен 1.',starter:'n = int(input())\nresult = 1\n',hint:'Начни с result = 1 и умножай его на каждое i из range(1, n + 1). Для нуля цикл будет пустым.',solution:'n = int(input())\nresult = 1\nfor i in range(1, n + 1):\n    result *= i\nprint(result)',tests:[io('5','120'),io('0','1'),io('1','1'),io('7','5040')]},
  {title:'Охота за гласными',brief:'Перебери буквы вместо чисел.',minutes:8,body:'Прочитай строку из строчных латинских букв. Посчитай, сколько в ней гласных <code>a, e, i, o, u</code>, и выведи число.',starter:'text = input()\ncount = 0\n',hint:'Перебери for letter in text. Если letter in "aeiou", увеличь count на 1.',solution:'text = input()\ncount = 0\nfor letter in text:\n    if letter in "aeiou":\n        count += 1\nprint(count)',tests:[io('hello','2'),io('python','1'),io('aeiou','5'),io('sky','0')]},
  {title:'Длина сообщения',brief:'У строки есть размер.',minutes:4,body:'Прочитай одну строку. Выведи количество символов в ней. Пробелы тоже считаются.',starter:'text = input()\n',hint:'Встроенная функция len(text) возвращает число символов.',solution:'text = input()\nprint(len(text))',tests:[io('Python','6'),io('hello world','11'),io('','0')]},
  {title:'Зеркало',brief:'Познакомься со срезами.',minutes:5,body:'Прочитай строку и выведи её в обратном порядке, сохранив все символы и регистр.',starter:'text = input()\n',hint:'Срез text[::-1] проходит по строке с шагом -1.',solution:'text = input()\nprint(text[::-1])',tests:[io('Python','nohtyP'),io('12345','54321'),io('a b','b a')]},
  {title:'Сумма списка',brief:'Много чисел в одной строке.',minutes:7,body:'На вход подаётся строка целых чисел, разделённых пробелами. Выведи их сумму.',starter:'numbers = list(map(int, input().split()))\n',hint:'Функция sum(numbers) складывает элементы. Можно также накопить сумму в цикле.',solution:'numbers = list(map(int, input().split()))\nprint(sum(numbers))',tests:[io('1 2 3 4 5','15'),io('-2 5 -3','0'),io('100','100')]},
  {title:'Без повторов',brief:'Посчитай уникальные значения.',minutes:7,body:'Прочитай непустую строку целых чисел через пробел. Выведи количество различных чисел. Например, для <code>1 2 2 3</code> ответ — 3.',starter:'numbers = list(map(int, input().split()))\n',hint:'Множество set(numbers) уберёт повторы. Возьми его длину.',solution:'numbers = list(map(int, input().split()))\nprint(len(set(numbers)))',tests:[io('1 2 2 3','3'),io('5 5 5','1'),io('-1 0 1 -1','3')]},
  {title:'Счётчик слов',brief:'Небольшая аналитика со словарём.',minutes:9,body:'Прочитай предложение из слов в нижнем регистре без знаков препинания. На следующей строке прочитай слово для поиска. Выведи, сколько раз это слово встретилось в предложении.',starter:'words = input().split()\ntarget = input()\n',hint:'Можно использовать words.count(target). Или собери словарь частот: counts[word] = counts.get(word, 0) + 1.',solution:'words = input().split()\ntarget = input()\ncounts = {}\nfor word in words:\n    counts[word] = counts.get(word, 0) + 1\nprint(counts.get(target, 0))',tests:[io('кот пёс кот\nкот','2'),io('python это интересно\nкод','0'),io('да да да\nда','3')]},
  {title:'Функция приветствия',brief:'Верни результат вместо вывода.',minutes:6,body:'Напиши функцию <code>greet(name)</code>, которая возвращает строку <code>Привет, ИМЯ!</code>. Читать ввод и вызывать print() не нужно.',starter:'def greet(name):\n    # Верни приветствие\n    pass\n',hint:'Используй return "Привет, " + name + "!". print() не заменяет return.',solution:'def greet(name):\n    return "Привет, " + name + "!"',tests:[fn('greet("Аня")','Привет, Аня!','greet("Аня")'),fn('greet("Марк")','Привет, Марк!','greet("Марк")')]},
  {title:'Квадрат числа',brief:'Одна функция — много вызовов.',minutes:5,body:'Напиши функцию <code>square(n)</code>, которая возвращает квадрат числа n. Она должна работать с положительными, отрицательными и дробными числами.',starter:'def square(n):\n    pass\n',hint:'Возведи число в степень с помощью n ** 2 и верни результат.',solution:'def square(n):\n    return n ** 2',tests:[fn('square(4)',16,'square(4)'),fn('square(-3)',9,'square(-3)'),fn('square(0)',0,'square(0)'),fn('square(1.5)',2.25,'square(1.5)')]},
  {title:'Проверка на чётность',brief:'Функция тоже может отвечать да или нет.',minutes:6,body:'Напиши функцию <code>is_even(n)</code>. Для чётного целого числа она возвращает логическое <code>True</code>, для нечётного — <code>False</code>. Нужны логические значения, а не строки.',starter:'def is_even(n):\n    pass\n',hint:'Выражение n % 2 == 0 уже даёт True или False. Его можно сразу вернуть.',solution:'def is_even(n):\n    return n % 2 == 0',tests:[fn('is_even(8)',true,'is_even(8)'),fn('is_even(7)',false,'is_even(7)'),fn('is_even(0)',true,'is_even(0)'),fn('is_even(-2)',true,'is_even(-2)')]},
  {title:'Палиндром',brief:'Соедини функции и работу со строками.',minutes:8,body:'Напиши функцию <code>is_palindrome(text)</code>, которая возвращает True, если строка читается одинаково в обе стороны. Игнорируй регистр и обычные пробелы. Других знаков во входных данных не будет.',starter:'def is_palindrome(text):\n    pass\n',hint:'Приведи строку к нижнему регистру text.lower(), удали пробелы .replace(" ", "") и сравни с перевёрнутой строкой.',solution:'def is_palindrome(text):\n    clean = text.lower().replace(" ", "")\n    return clean == clean[::-1]',tests:[fn('is_palindrome("Топот")',true,'is_palindrome("Топот")'),fn('is_palindrome("А роза упала на лапу Азора")',true,'Проверка фразы'),fn('is_palindrome("Python")',false,'is_palindrome("Python")'),fn('is_palindrome("")',true,'Пустая строка')]},
  {title:'Мини-проект: анализатор',brief:'Твой первый полезный инструмент.',minutes:12,body:'Создай функцию <code>analyze(numbers)</code>, которая принимает непустой список чисел и возвращает словарь с ключами <code>"sum"</code> (сумма), <code>"min"</code> (минимум), <code>"max"</code> (максимум) и <code>"average"</code> (среднее арифметическое). Пример: для [2, 4, 6] результат — {"sum": 12, "min": 2, "max": 6, "average": 4.0}.',starter:'def analyze(numbers):\n    # Собери словарь со статистикой\n    pass\n',hint:'Используй sum(), min(), max() и len(). Среднее — sum(numbers) / len(numbers). Верни словарь через return.',solution:'def analyze(numbers):\n    return {\n        "sum": sum(numbers),\n        "min": min(numbers),\n        "max": max(numbers),\n        "average": sum(numbers) / len(numbers)\n    }',tests:[fn('analyze([2, 4, 6])',{sum:12,min:2,max:6,average:4},'analyze([2, 4, 6])'),fn('analyze([-5, 0, 5])',{sum:0,min:-5,max:5,average:0},'analyze([-5, 0, 5])'),fn('analyze([7])',{sum:7,min:7,max:7,average:7},'analyze([7])')]}
].map((task,id)=>({...task,id,module:Math.floor(id/5),number:id%5+1,xp:20+Math.floor(id/5)*10}));

// Version 2 keeps every original task and extends the foundation curriculum.
const oldModules=modules.map(m=>({...m}));
const oldTasks=tasks.map(t=>({...t,legacyId:t.id}));
const simpleTypesTheory=`<h3>У каждого значения есть тип</h3><p><code>int</code> — целое число, <code>float</code> — дробное, <code>str</code> — текст, <code>bool</code> — True или False. <code>None</code> означает отсутствие значения.</p><pre>count = 42\nprice = 3.5\nname = "Python"\nready = True\nresult = None\nprint(type(count).__name__)  # int</pre><p>Типы преобразуются функциями <code>int()</code>, <code>float()</code>, <code>str()</code>. Ввод всегда приходит строкой. Для дробного числа используй точку.</p><pre>age = int(input())\nprint("Мне " + str(age) + " лет")\nprint(age >= 18)  # True или False\nprint(result is None)  # True</pre><p>Для сравнения значений используют <code>==</code>, для проверки отсутствия — <code>is None</code>. <code>True</code>, <code>False</code> и <code>None</code> пишутся с заглавной буквы, без кавычек.</p>`;
const importsTheory=`<h3>Новые типы из стандартной библиотеки</h3><p>Некоторые полезные типы нужно импортировать. Они уже входят в Python: устанавливать библиотеки не требуется.</p><pre>from decimal import Decimal, ROUND_HALF_UP\nfrom fractions import Fraction\nfrom datetime import date, timedelta</pre><p><code>Decimal</code> точно хранит десятичные значения. Передавай строку: двоичная погрешность float иначе попадёт в Decimal.</p><pre>print(Decimal("0.1") + Decimal("0.2"))  # 0.3\nprice = Decimal("12.345")\nprint(price.quantize(Decimal("0.01"),\n    rounding=ROUND_HALF_UP))  # 12.35</pre><p><code>Fraction</code> хранит обыкновенные дроби и автоматически сокращает результат.</p><pre>print(Fraction("1/2") + Fraction("1/3"))  # 5/6</pre><p><code>date</code> хранит календарную дату, <code>timedelta</code> — временной интервал. Формат ISO для даты: ГГГГ-ММ-ДД.</p><pre>start = date.fromisoformat("2024-02-28")\nend = start + timedelta(days=2)\nprint(end)                 # 2024-03-01\nprint((end - start).days)  # 2\nprint(timedelta(seconds=3661))  # 1:01:01</pre>`;
modules.splice(0,modules.length,
  {...oldModules[0],title:'Погружение в Python'},
  {...oldModules[1],title:'Простые типы данных',subtitle:'Поймём, из чего состоит код',tags:['int · float','str · bool','None'],description:'Изучай типы значений, преобразования и вычисления.',theory:simpleTypesTheory+oldModules[1].theory},
  {...oldModules[2],title:'Ветвления'},
  {title:'Импортируемые типы данных',subtitle:'Откроем стандартную библиотеку',icon:'download',color:'blue',tags:['Decimal','Fraction','datetime'],description:'Считай точно и работай с датами и интервалами.',theory:importsTheory},
  {...oldModules[4],title:'Коллекции',theory:`<h3>Строки, списки, множества и словари</h3><p>Строка хранит символы, список — последовательность значений, множество — уникальные элементы, словарь — пары ключей и значений.</p><pre>text = "python"\nprint(len(text))   # 6\nprint(text[::-1])  # nohtyp\nnums = list(map(int, input().split()))\nprint(sum(nums))\nprint(len(set(nums)))\nprofile = {"name": "Аня", "level": 1}\nprint(profile["name"])\nprint(profile.get("score", 0))</pre><p><code>split()</code> делит строку на слова. <code>map(int, ...)</code> превращает их в числа. У списка есть метод <code>count()</code>, который считает вхождения.</p><pre>words = "кот пёс кот".split()\nprint(words.count("кот"))  # 2</pre>`},
  {...oldModules[3],title:'Итерации и циклы'},
  oldModules[5]
);
modules.forEach((m,id)=>m.id=id);
const simpleTypeTasks=[
  {title:'Типы повсюду',brief:'Узнай тип каждого значения.',minutes:5,body:'Выведи названия типов значений <code>42</code>, <code>3.5</code>, <code>"Python"</code> и <code>True</code>, каждое с новой строки. Используй <code>type(value).__name__</code>. Ожидается: int, float, str, bool.',starter:'# Пример: print(type(42).__name__)\n',hint:'type(значение) возвращает тип, а .__name__ — его короткое название. Сделай четыре вызова print().',solution:'print(type(42).__name__)\nprint(type(3.5).__name__)\nprint(type("Python").__name__)\nprint(type(True).__name__)',tests:[io('','int\nfloat\nstr\nbool')]},
  {title:'Из строки в число',brief:'Строку сначала нужно преобразовать.',minutes:5,body:'Прочитай целое число из строки ввода, преобразуй его через <code>int()</code> и выведи удвоенное значение. Умножение строки повторяет текст, поэтому тип здесь важен.',starter:'text = input()\n',hint:'Сохрани number = int(text), затем выведи number * 2.',solution:'text = input()\nnumber = int(text)\nprint(number * 2)',tests:[io('21','42'),io('-7','-14'),io('0','0')]},
  {title:'Из числа в текст',brief:'Соедини возраст с сообщением.',minutes:5,body:'Прочитай целое число — возраст. Выведи <code>Мне N лет</code>, подставив число вместо N. Для соединения с текстом преобразуй число через <code>str()</code>.',starter:'age = int(input())\n',hint:'Число и строку нельзя сложить напрямую. Используй "Мне " + str(age) + " лет".',solution:'age = int(input())\nprint("Мне " + str(age) + " лет")',tests:[io('18','Мне 18 лет'),io('7','Мне 7 лет'),io('25','Мне 25 лет')]},
  {title:'Логический ответ',brief:'Сравнение возвращает значение bool.',minutes:5,body:'Прочитай целое число. Выведи <code>True</code>, если оно больше нуля, и <code>False</code> в остальных случаях. Можно вывести само выражение сравнения, без if.',starter:'number = int(input())\n',hint:'Выражение number > 0 уже даёт логическое значение. Передай его в print().',solution:'number = int(input())\nprint(number > 0)',tests:[io('5','True'),io('0','False'),io('-2','False')]},
  {title:'Когда значения нет',brief:'Познакомься с None.',minutes:5,body:'Создай переменную <code>result</code> со значением <code>None</code>. Выведи результат проверки <code>result is None</code>. Должно получиться <code>True</code>.',starter:'# None пишется без кавычек\n',hint:'Сначала result = None, затем print(result is None). Строка "None" — другое значение.',solution:'result = None\nprint(result is None)',required:'"result" in ns and ns["result"] is None',tests:[io('','True')]}
];
const importTasks=[
  {title:'Точная десятичная сумма',brief:'Сложи десятичные числа без погрешности.',minutes:7,body:'Прочитай два десятичных числа с отдельных строк. Создай из строк объекты <code>Decimal</code>, сложи и выведи результат. В этой задаче не преобразуй ввод в float.',starter:'from decimal import Decimal\n\na = Decimal(input())\n',hint:'Вторая строка читается так же: b = Decimal(input()). Затем print(a + b).',solution:'from decimal import Decimal\na = Decimal(input())\nb = Decimal(input())\nprint(a + b)',tests:[io('0.1\n0.2','0.3'),io('1.25\n2.75','4.00'),io('-0.5\n0.3','-0.2')]},
  {title:'Точный чек',brief:'Округли деньги по понятному правилу.',minutes:8,body:'Прочитай десятичную цену и целое количество с отдельных строк. Умножь цену на количество и выведи сумму с двумя знаками после точки. Используй Decimal и <code>quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)</code>.',starter:'from decimal import Decimal, ROUND_HALF_UP\nprice = Decimal(input())\nquantity = int(input())\n',hint:'Сначала total = price * quantity, затем примени total.quantize(...). ROUND_HALF_UP округляет половину вверх.',solution:'from decimal import Decimal, ROUND_HALF_UP\nprice = Decimal(input())\nquantity = int(input())\ntotal = price * quantity\nprint(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))',tests:[io('12.345\n1','12.35'),io('0.10\n3','0.30'),io('19.99\n2','39.98')]},
  {title:'Дроби без потерь',brief:'Сложи и сократи обыкновенные дроби.',minutes:7,body:'Прочитай две дроби в формате <code>числитель/знаменатель</code> с отдельных строк. Сложи их как объекты Fraction и выведи результат. Fraction сам сократит дробь; целый результат выводится без знаменателя.',starter:'from fractions import Fraction\n',hint:'Fraction(input()) читает дробь из строки. Сложи две дроби и используй print().',solution:'from fractions import Fraction\na = Fraction(input())\nb = Fraction(input())\nprint(a + b)',tests:[io('1/2\n1/3','5/6'),io('1/4\n3/4','1'),io('-1/2\n1/6','-1/3')]},
  {title:'Дни между датами',brief:'У календаря свои правила.',minutes:8,body:'Прочитай начальную и конечную даты в формате ГГГГ-ММ-ДД с отдельных строк. Выведи число дней между ними. Используй <code>date.fromisoformat()</code> и свойство <code>.days</code> разности дат.',starter:'from datetime import date\n',hint:'start = date.fromisoformat(input()), end — аналогично. Выведи (end - start).days. Високосный год учтётся сам.',solution:'from datetime import date\nstart = date.fromisoformat(input())\nend = date.fromisoformat(input())\nprint((end - start).days)',tests:[io('2024-02-28\n2024-03-01','2'),io('2025-01-01\n2025-01-11','10'),io('2026-11-17\n2026-11-17','0')]},
  {title:'Дата через n дней',brief:'Прибавь к дате временной интервал.',minutes:8,body:'Прочитай дату в формате ГГГГ-ММ-ДД, затем целое число дней. Прибавь к дате <code>timedelta(days=n)</code> и выведи новую дату. Число дней может быть отрицательным.',starter:'from datetime import date, timedelta\n',hint:'Создай дату через date.fromisoformat(input()), прочитай n и выведи start + timedelta(days=n).',solution:'from datetime import date, timedelta\nstart = date.fromisoformat(input())\nn = int(input())\nprint(start + timedelta(days=n))',tests:[io('2024-02-28\n2','2024-03-01'),io('2025-12-31\n1','2026-01-01'),io('2026-01-01\n-1','2025-12-31')]}
];
// Lists come before loops; count() solves the word-count exercise without a loop.
oldTasks[24].solution='words = input().split()\ntarget = input()\nprint(words.count(target))';
const grouped=[oldTasks.slice(0,5),[...simpleTypeTasks,...oldTasks.slice(5,10)],oldTasks.slice(10,15),importTasks,oldTasks.slice(20,25),oldTasks.slice(15,20),oldTasks.slice(25,30)];
tasks.splice(0,tasks.length,...grouped.flatMap((group,module)=>group.map((t,index)=>({...t,module,number:index+1,xp:20+module*10}))).map((t,id)=>({...t,id})));
export const legacyIdMap=Object.fromEntries(tasks.filter(t=>t.legacyId!==undefined).map(t=>[t.legacyId,t.id]));
